intersection-of-two-arrays-ii:
from collections import Counter
class Solution:
    def intersect(self, nums1: List[int], nums2: List[int]) -> List[int]:
        c1, res = Counter(nums1), []
        for n in nums2:
            if c1[n] > 0:
                c1[n] -= 1
                res.append(n)
        return res

